def make_handlers(names, base_config=None):
    if base_config is None:
        base_config = {}

    handlers = []
    for name in names:
        # Create a closure that captures the current value of name
        handler = lambda name=name: f"{name}:{len(base_config)}"
        handlers.append(handler)

    return handlers

